refentry.refsect1:
&reftitle.changelog;







     &Version;
     &Description;





     8.3.0

      Ora emette un E_WARNING quando token non viene fornito.

  &reftitle.examples;



    Esempio di strtok


<?php
$string = "Questa è\tuna stringa\ndi esempio";
/* Usa anche tabulazione e a capo come caratteri di separazione */
$tok = strtok($string, " \n\t");

while ($tok !== false) {
    echo "Parola={$tok}\n";
    $tok = strtok(" \n\t");
}
?>







    Comportamento di strtok quando trova una parte vuota


<?php
$first_token  = strtok('/qualcosa', '/');
$second_token = strtok('/');
var_dump($first_token, $second_token);
?>


    &example.outputs;


string(8) "qualcosa"
bool(false)







    La differenza tra strtok ed explode


<?php
$string = ";aaa;;bbb;";

$parts = [];
$tok = strtok($string, ";");
while ($tok !== false) {
    $parts[] = $tok;
    $tok = strtok(";");
}
echo json_encode($parts),"\n";

$parts = explode(";", $string);
echo json_encode($parts),"\n";


    &example.outputs;


["aaa","bbb"]
["","aaa","","bbb",""]
